D=Path(__file__).resolve().parents[1];source=json.loads((D/'results/pne_opposite_comparisons.json').read_text());names=['C0','M0','M1','C2'];I=tuple(range(4));X=(3,2,1,0);then=lambda p,q:tuple(q[i] for i in p);edge=lambda e,p:tuple(sorted(p[i] for i in e));act=lambda E,p:frozenset(edge(e,p) for e in E);E0=frozenset([(0,1),(2,3)]);E1=frozenset([(0,3),(1,2)]);assert set(source['windows'])=={'C0/M0','M0/M1','C2/M1'};Ys=[p for p in itertools.permutations(I) if then(p,p)==I and act(E0,p)==E1];rows=[]
